          <div className="input-group">
            <label className="label">Plaka <span style={{ color: "var(--turuncu)" }}>*</span></label>
            <input className="input" placeholder="34 ABC 123" value={form.plaka} onChange={e => set("plaka", e.target.value.toUpperCase())} />
            <Hata alan="plaka" />
          </div>
        </div>
      )}

      {rol === "issiz" && (
        <div className="card" style={{ padding: 20, marginBottom: 12 }}>
          <div className="label" style={{ marginBottom: 14 }}>🏢 Firma Bilgileri</div>
          <div className="input-group">
            <label className="label">Firma Adı <span style={{ color: "var(--turuncu)" }}>*</span></label>
            <input className="input" placeholder="Örnek Taşımacılık A.Ş." value={form.firmaAdi} onChange={e => set("firmaAdi", e.target.value)} />
