        <div className="label" style={{ marginBottom: 14 }}>🔒 Şifre Belirle</div>
        <div className="input-group">
          <label className="label">Şifre <span style={{ color: "var(--turuncu)" }}>*</span></label>
          <input className="input" type="password" placeholder="En az 6 karakter" value={form.sifre} onChange={e => set("sifre", e.target.value)} />
          <Hata alan="sifre" />
        </div>
        <div className="input-group" style={{ marginBottom: 0 }}>
          <label className="label">Şifre Tekrar <span style={{ color: "var(--turuncu)" }}>*</span></label>
