      </button>
    </div>
  );
};

export default function GirisEkrani() {
  const { kayitOl, girisYap } = useApp();
  const [ekran, setEkran] = useState("ana"); // ana | kayit-rol | kayit-form | giris
  const [secRol, setSecRol] = useState(null);
  const [girisForm, setGirisForm] = useState({ telefon: "", sifre: "" });

  const handleKayit = (bilgiler) => {
    kayitOl(bilgiler);
  };

  const handleGiris = () => {
    // Demo: telefon + şifre kontrolü basit
    if (girisForm.telefon && girisForm.sifre) {
      girisYap("kamyoncu", "Demo Kullanıcı");
    }
  };

  if (ekran === "kayit-form") return (
    <div style={{ minHeight: "100vh", background: "var(--bg)", padding: 20, overflowY: "auto" }}>
      <div style={{ maxWidth: 440, margin: "0 auto", paddingTop: 20 }}>
        <KayitFormu rol={secRol} onGeri={() => setEkran("kayit-rol")} onTamam={handleKayit} />
      </div>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", background: "var(--bg)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 24, position: "relative", overflow: "hidden" }}>
      {/* Arkaplan */}
      <div style={{ position: "absolute", top: -120, left: -120, width: 400, height: 400, background: "radial-gradient(circle, rgba(232,82,10,0.07) 0%, transparent 70%)", pointerEvents: "none" }} />
      <div style={{ position: "absolute", bottom: -80, right: -80, width: 300, height: 300, background: "radial-gradient(circle, rgba(245,166,35,0.05) 0%, transparent 70%)", pointerEvents: "none" }} />

      <div style={{ width: "100%", maxWidth: 400, animation: "slideDown 0.35s ease" }}>
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: 40 }}>
          <div style={{ fontFamily: "var(--font-d)", fontSize: 56, letterSpacing: 5, lineHeight: 1, marginBottom: 8 }}>
            NAKLI<span style={{ color: "var(--turuncu)" }}>YOL</span>
          </div>
          <div className="label">Türkiye'nin Kamyon Platformu</div>
        </div>

        {ekran === "ana" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <button onClick={() => setEkran("kayit-rol")} className="btn btn-primary btn-display btn-full">
              KAYIT OL — ÜCRETSİZ
            </button>
            <button onClick={() => setEkran("giris")} className="btn btn-secondary btn-full" style={{ fontWeight: 500 }}>
              Zaten hesabım var — Giriş Yap
            </button>
            <div style={{ textAlign: "center", marginTop: 12 }}>
              <div className="label" style={{ marginBottom: 10 }}>VEYA HIZLI GİRİŞ</div>
              <div style={{ display: "flex", gap: 8 }}>
                {roller.map(r => (
                  <button key={r.key} onClick={() => girisYap(r.key, "Demo " + r.baslik)} style={{ flex: 1, background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r)", padding: "10px 8px", color: "var(--text)", cursor: "pointer", fontSize: 12, transition: "var(--tr)" }}
                    onMouseEnter={e => e.currentTarget.style.borderColor = r.renk}
                    onMouseLeave={e => e.currentTarget.style.borderColor = "var(--border)"}
                  >
                    <span style={{ fontSize: 20, display: "block", marginBottom: 4 }}>{r.icon}</span>
                    {r.baslik} Demo
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {ekran === "kayit-rol" && (
          <div style={{ animation: "slideDown 0.25s ease" }}>
            <button onClick={() => setEkran("ana")} style={{ color: "var(--text3)", fontSize: 13, marginBottom: 16, display: "flex", alignItems: "center", gap: 6 }}>← Geri</button>
            <div className="label" style={{ textAlign: "center", marginBottom: 14 }}>Nasıl kullanacaksınız?</div>
            {roller.map(r => (
              <button key={r.key} onClick={() => { setSecRol(r.key); setEkran("kayit-form"); }} style={{ width: "100%", background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: "18px 20px", display: "flex", alignItems: "center", gap: 16, cursor: "pointer", transition: "var(--tr)", marginBottom: 10, color: "var(--text)", textAlign: "left" }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = r.renk; e.currentTarget.style.background = "var(--bg2)"; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = "var(--border)"; e.currentTarget.style.background = "var(--bg1)"; }}
              >
                <span style={{ fontSize: 34 }}>{r.icon}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "var(--font-d)", fontSize: 20, letterSpacing: 1, color: r.renk }}>{r.baslik}</div>
                  <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>{r.aciklama}</div>
                </div>
                <span style={{ color: "var(--text3)", fontSize: 20 }}>›</span>
              </button>
            ))}
          </div>
        )}

        {ekran === "giris" && (
          <div style={{ animation: "slideDown 0.25s ease" }}>
            <button onClick={() => setEkran("ana")} style={{ color: "var(--text3)", fontSize: 13, marginBottom: 16, display: "flex", alignItems: "center", gap: 6 }}>← Geri</button>
            <div className="card" style={{ padding: 24 }}>
              <div className="display" style={{ fontSize: 24, marginBottom: 4 }}>Giriş Yap</div>
              <div className="label" style={{ marginBottom: 20 }}>Hesabınıza erişin</div>
              <div className="input-group">
                <label className="label">Telefon</label>
                <div className="input-phone">
                  <div className="phone-prefix">🇹🇷 +90</div>
                  <input className="input" placeholder="5xx xxx xx xx" value={girisForm.telefon} onChange={e => setGirisForm(f => ({ ...f, telefon: e.target.value }))} />
                </div>
              </div>
              <div className="input-group">
                <label className="label">Şifre</label>
                <input className="input" type="password" placeholder="••••••" value={girisForm.sifre} onChange={e => setGirisForm(f => ({ ...f, sifre: e.target.value }))} onKeyDown={e => e.key === "Enter" && handleGiris()} />
              </div>
              <button style={{ fontSize: 12, color: "var(--sari)", marginBottom: 16, cursor: "pointer" }}>Şifremi unuttum</button>
              <button onClick={handleGiris} disabled={!girisForm.telefon || !girisForm.sifre} className="btn btn-primary btn-display btn-full">
                GİRİŞ YAP
              </button>
            </div>
          </div>
        )}

        <div style={{ textAlign: "center", marginTop: 28, fontSize: 11, color: "var(--text3)" }}>NakliYol © 2026</div>
      </div>
    </div>
  );
}
